// Redux Toolkit functions:
// createSlice → creates reducer + actions
// createAsyncThunk → used for async API logic (fetch, upload, etc)
import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import axios from "axios"; // Axios for HTTP requests
import * as ENV from "../config"; // ENV config for API URLs

// ---------------- INITIAL STATE ----------------
const initialState = {
  user: JSON.parse(localStorage.getItem("loggedUser")) || null, // logged user
  role: localStorage.getItem("role") || null, // student or company
  isLoading: false,
  isSuccess: false,
  isError: false,
  message: "",
};

// ---------------- FETCH USER ----------------
export const fetchUser = createAsyncThunk(
  "users/fetchUser",
  async (email, thunkAPI) => {
    try {
      const res = await axios.get(`${ENV.SERVER_URL}/user/${email}`);
      return res.data; // return user data
    } catch {
      return thunkAPI.rejectWithValue("Fetch failed");
    }
  }
);

// ---------------- UPLOAD CV ----------------
export const uploadCv = createAsyncThunk(
  "users/uploadCv",
  async ({ file, email }, thunkAPI) => {
    try {
      const formData = new FormData(); // prepare file
      formData.append("cv", file);
      formData.append("email", email);

      const res = await axios.post(`${ENV.SERVER_URL}/uploadCV`, formData);
      return res.data.cvLink; // return uploaded CV link
    } catch {
      return thunkAPI.rejectWithValue("Upload failed");
    }
  }
);

// ---------------- DELETE CV ----------------
export const deleteCvThunk = createAsyncThunk(
  "users/deleteCv",
  async (email, thunkAPI) => {
    try {
      await axios.put(`${ENV.SERVER_URL}/deleteCV`, { email });
      return true; // success
    } catch {
      return thunkAPI.rejectWithValue("Delete failed");
    }
  }
);

// ---------------- UPDATE BANK CARD ----------------
export const updateBankCardThunk = createAsyncThunk(
  "users/updateBankCard",
  async (data, thunkAPI) => {
    try {
      const res = await axios.put(`${ENV.SERVER_URL}/updateBankCard`, data);
      return res.data.user; // updated user
    } catch {
      return thunkAPI.rejectWithValue("Bank update failed");
    }
  }
);

// ---------------- DELETE BANK CARD ----------------
export const deleteBankCardThunk = createAsyncThunk(
  "users/deleteBankCard",
  async (email, thunkAPI) => {
    try {
      const res = await axios.put(`${ENV.SERVER_URL}/updateBankCard`, {
        email,
        bankName: "",
        cardNumber: "",
        cardName: "",
        expiry: "",
        cvv: "",
      });
      return res.data.user; // updated user after delete
    } catch {
      return thunkAPI.rejectWithValue("Bank delete failed");
    }
  }
);

// ---------------- SLICE ----------------
const userSlice = createSlice({
  name: "users",
  initialState,
  reducers: {
    // Reset loading/error states
    resetState: (state) => {
      state.isLoading = false;
      state.isSuccess = false;
      state.isError = false;
      state.message = "";
    },
  },

  // ---------------- HANDLE ASYNC RESULTS ----------------
  extraReducers: (builder) => {
    builder
      // FETCH USER
      .addCase(fetchUser.fulfilled, (state, action) => {
        state.user = action.payload;
      })

      // UPLOAD CV
      .addCase(uploadCv.fulfilled, (state, action) => {
        state.user.cvLink = action.payload;
      })

      // DELETE CV
      .addCase(deleteCvThunk.fulfilled, (state) => {
        state.user.cvLink = null;
      })

      // UPDATE BANK CARD
      .addCase(updateBankCardThunk.fulfilled, (state, action) => {
        state.user = action.payload;
      })

      // DELETE BANK CARD
      .addCase(deleteBankCardThunk.fulfilled, (state, action) => {
        state.user = action.payload;
      });
  },
});

// Export reducer + actions
export const { resetState } = userSlice.actions;
export default userSlice.reducer;
